# NVIDIA Terraform config for NGC AWS Tutorial.
# Copyright (c) 2017, NVIDIA CORPORATION.  All rights reserved.

# AWS Provider
provider "aws" {
  region = "${var.region}"

  # Only uncomment and place keys here if do not have the AWS CLI.
  # If you put your keys here, do NOT share this file with anyone.
  #access_key = "XXXXXXXX"
  #secret_key = "XXXXXXXX"
}

# Select the latest AMI in Marketplace.
data "aws_ami" "nv_volta_dl_ami" {
  owners = ["679593333241"]

  filter {
    name   = "name"
    values = ["NVIDIA Volta Deep Learning AMI*"]
  }

  most_recent = true
}

# To us spot instances rather than on demand:
# 1) Update the resource below to start with the commented out code.
# 2) Set your max price.
# 3) Update the outputs from "aws_instance" to "aws_spot_instance_request".
# https://www.terraform.io/docs/providers/aws/r/spot_instance_request.html
#
#resource "aws_spot_instance_request" "dl_instance" {
#  spot_price = "x.xx"           # Max price
#  wait_for_fulfillment = true   # wait up to 10m to be fulfilled

resource "aws_instance" "dl_instance" {
  ami           = "${data.aws_ami.nv_volta_dl_ami.id}"
  instance_type = "${var.instance-type}"

  tags {
    Name = "${var.name}"
  }

  root_block_device {
    volume_size           = "${var.ebs-size}"
    volume_type           = "gp2"
    delete_on_termination = true
  }

  key_name        = "${var.key-name}"
  security_groups = ["${var.security-group}"]
}

# NVIDIA Terraform config for NGC AWS Tutorial.
# Copyright (c) 2017, NVIDIA CORPORATION.  All rights reserved.

# Terraform outputs

output "id" {
  value = "${aws_instance.dl_instance.id}"
}

output "key-name" {
  value = "${aws_instance.dl_instance.key_name}"
}

output "public-dns" {
  value = "${aws_instance.dl_instance.public_dns}"
}

output "ssh-cmd" {
  value = "${format("ssh -i %s%s.pem ubuntu@%s", var.ssh-key-dir,
    aws_instance.dl_instance.key_name,
    aws_instance.dl_instance.public_dns)}"
}

# NVIDIA Terraform config for NGC AWS Tutorial.
# Copyright (c) 2017, NVIDIA CORPORATION.  All rights reserved.

# Check that the variables are correct for your usage.
# The defaults follow those in the NGC AWS Tutorial.

variable "name" {
  default     = "My Volta 1GPU"
  description = "Name to tag the instance"
}

variable "key-name" {
  default     = "my-key-pair"
  description = "AWS keypair to use"
}

variable "ssh-key-dir" {
  default     = "~/.ssh/"
  description = "Path to SSH keys - include ending '/'"
}

variable "region" {
  default     = "us-west-2"
  description = "AWS Region"
}

variable "instance-type" {
  default     = "p3.2xlarge"
  description = "AWS Instance Type"
}

variable "security-group" {
  default     = "my-sg"
  description = "Predefined Security Group"
}

variable "ebs-size" {
  default     = 32
  description = "Size of Root EBF partition, 32 GiB is default"
}
